test('renderInvoiceText handles 0% VAT products', () => {
  const invoice = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-07',
    lines: [{ sku: 'WORKSHOP-DAY', qty: 2 }],
  }).value;
  const text = renderInvoiceText(invoice);
  assert.ok(text.includes('Brand workshop (day, VAT exempt)'));
  assert.ok(text.includes('Total:'));
  assert(!text.includes('VAT:'));
});

test('renderInvoiceText shows VAT correctly with discount', () => {
  const invoice = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5, discountPercent: 10 }],
  }).value;
  const text = renderInvoiceText(invoice);
  assert.ok(text.includes('Subtotal:'));
  assert.ok(text.includes('Discount:'));
  assert.ok(text.includes('VAT:'));
  const lines = text.split('\n');
  const lastLine = lines[lines.length - 1];
  assert.ok(lastLine.startsWith('Total:'));
});

