import test from 'node:test';
import assert from 'node:assert/strict';
import { renderInvoiceText } from '../src/render.js';
import { createInvoice, issueInvoice, applyVoucher } from '../src/invoices.js';
import { recordPayment } from '../src/payments.js';

test('renderInvoiceText shows DRAFT for draft invoices', () => {
  const invoice = createInvoice({
    customerId: 'C-003',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  }).value;
  const text = renderInvoiceText(invoice);
  assert.ok(text.startsWith('DRAFT\n'));
});

test('renderInvoiceText shows invoice number for issued invoices', () => {
  const invoice = createInvoice({
    customerId: 'C-003',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  }).value;
  const issued = issueInvoice(invoice, []).value;
  const text = renderInvoiceText(issued);
  assert.ok(text.startsWith('INV-2026-0001\n'));
});

test('renderInvoiceText includes customer name', () => {
  const invoice = createInvoice({
    customerId: 'C-003',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  }).value;
  const text = renderInvoiceText(invoice);
  const lines = text.split('\n');
  assert.equal(lines[1], 'Kite & Co');
});

test('renderInvoiceText shows one line per invoice line', () => {
  const invoice = createInvoice({
    customerId: 'C-003',
    issueDate: '2026-10-07',
    lines: [
      { sku: 'DES-HOUR', qty: 5 },
      { sku: 'DEV-HOUR', qty: 3 },
    ],
  }).value;
  const text = renderInvoiceText(invoice);
  assert.ok(text.includes('5 × Design work (hour)'));
  assert.ok(text.includes('3 × Development (hour)'));
});

test('renderInvoiceText formats prices as euros', () => {
  const invoice = createInvoice({
    customerId: 'C-003',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  }).value;
  const text = renderInvoiceText(invoice);
  assert.ok(text.includes('€85.00'));
  assert.ok(text.includes('€425.00'));
});

test('renderInvoiceText shows line totals', () => {
  const invoice = createInvoice({
    customerId: 'C-003',
    issueDate: '2026-10-07',
    lines: [
      { sku: 'DES-HOUR', qty: 5 },
      { sku: 'DEV-HOUR', qty: 3 },
    ],
  }).value;
  const text = renderInvoiceText(invoice);
  assert.ok(text.includes('= €425.00'));
  assert.ok(text.includes('= €285.00'));
});

test('renderInvoiceText shows total at the end without discount', () => {
  const invoice = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-07',
    lines: [
      { sku: 'WORKSHOP-DAY', qty: 1 },
      { sku: 'TALK', qty: 1 },
    ],
  }).value;
  const text = renderInvoiceText(invoice);
  const lines = text.split('\n');
  const lastLine = lines[lines.length - 1];
  assert.equal(lastLine, 'Total: €950.00');
});

test('renderInvoiceText handles single line invoice', () => {
  const invoice = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-07',
    lines: [{ sku: 'WORKSHOP-DAY', qty: 1 }],
  }).value;
  const text = renderInvoiceText(invoice);
  const lines = text.split('\n');
  assert.equal(lines[0], 'DRAFT');
  assert.equal(lines[1], 'Blue Fern Bakery');
  assert.ok(lines[3].includes('Brand workshop (day, VAT exempt)'));
  assert.equal(lines[5], 'Total: €600.00');
});

test('renderInvoiceText handles large quantities', () => {
  const invoice = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-07',
    lines: [{ sku: 'WORKSHOP-DAY', qty: 1 }],
  }).value;
  const text = renderInvoiceText(invoice);
  assert.ok(text.includes('Brand workshop'));
  assert.ok(text.includes('€600.00'));
  assert.ok(text.includes('Total: €600.00'));
});

test('renderInvoiceText handles products with VAT rate 0', () => {
  const invoice = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-07',
    lines: [{ sku: 'WORKSHOP-DAY', qty: 2 }],
  }).value;
  const text = renderInvoiceText(invoice);
  assert.ok(text.includes('Brand workshop (day, VAT exempt)'));
  assert.ok(text.includes('€600.00'));
  assert.ok(text.includes('Total: €1,200.00'));
});

test('renderInvoiceText shows all required fields', () => {
  const invoice = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-07',
    lines: [{ sku: 'WORKSHOP-DAY', qty: 1 }],
  }).value;
  const text = renderInvoiceText(invoice);
  const lines = text.split('\n');
  assert.equal(lines[0], 'DRAFT');
  assert.equal(lines[1], 'Blue Fern Bakery');
  assert.equal(lines[2], '');
  assert.ok(lines[3].includes('×'));
  assert.ok(lines[3].includes('@'));
  assert.ok(lines[3].includes('='));
  assert.equal(lines[4], '');
  assert.ok(lines[5].startsWith('Total:'));
  assert.ok(lines[5].includes('€'));
});

test('renderInvoiceText shows discount on line when present', () => {
  const invoice = createInvoice({
    customerId: 'C-003',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5, discountPercent: 10 }],
  }).value;
  const text = renderInvoiceText(invoice);
  assert.ok(text.includes('- €42.50 ='));
});

test('renderInvoiceText shows subtotal and discount line when invoice has discounts', () => {
  const invoice = createInvoice({
    customerId: 'C-003',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5, discountPercent: 10 }],
  }).value;
  const text = renderInvoiceText(invoice);
  assert.ok(text.includes('Subtotal: €425.00'));
  assert.ok(text.includes('Discount: -€42.50'));
});

test('renderInvoiceText shows correct total with discount', () => {
  const invoice = createInvoice({
    customerId: 'C-003',
    issueDate: '2026-10-07',
    lines: [{ sku: 'WORKSHOP-DAY', qty: 1, discountPercent: 10 }],
  }).value;
  const text = renderInvoiceText(invoice);
  const lines = text.split('\n');
  const lastLine = lines[lines.length - 1];
  assert.equal(lastLine, 'Total: €540.00');
});

test('renderInvoiceText handles mixed discounted and non-discounted lines', () => {
  const invoice = createInvoice({
    customerId: 'C-003',
    issueDate: '2026-10-07',
    lines: [
      { sku: 'DES-HOUR', qty: 5, discountPercent: 10 },
      { sku: 'DEV-HOUR', qty: 3 },
    ],
  }).value;
  const text = renderInvoiceText(invoice);
  assert.ok(text.includes('Subtotal:'));
  assert.ok(text.includes('Discount:'));
  const lines = text.split('\n');
  const lastLine = lines[lines.length - 1];
  assert.ok(lastLine.startsWith('Total:'));
});

test('renderInvoiceText shows VAT when present', () => {
  const invoice = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  }).value;
  const text = renderInvoiceText(invoice);
  assert.ok(text.includes('VAT: €'));
});

test('renderInvoiceText shows VAT above total', () => {
  const invoice = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  }).value;
  const text = renderInvoiceText(invoice);
  const lines = text.split('\n');
  const vatLineIndex = lines.findIndex((line) => line.startsWith('VAT:'));
  const totalLineIndex = lines.findIndex((line) => line.startsWith('Total:'));
  assert(vatLineIndex >= 0);
  assert(totalLineIndex > vatLineIndex);
});

test('renderInvoiceText shows subtotal when VAT is present but no discount', () => {
  const invoice = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  }).value;
  const text = renderInvoiceText(invoice);
  assert.ok(text.includes('Subtotal:'));
  assert.ok(text.includes('VAT:'));
  const lines = text.split('\n');
  const lastLine = lines[lines.length - 1];
  assert.ok(lastLine.startsWith('Total:'));
});

test('renderInvoiceText handles 0% VAT products', () => {
  const invoice = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-07',
    lines: [{ sku: 'WORKSHOP-DAY', qty: 2 }],
  }).value;
  const text = renderInvoiceText(invoice);
  assert.ok(text.includes('Brand workshop (day, VAT exempt)'));
  assert.ok(text.includes('Total:'));
  assert(!text.includes('VAT:'));
});

test('renderInvoiceText shows VAT correctly with discount', () => {
  const invoice = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5, discountPercent: 10 }],
  }).value;
  const text = renderInvoiceText(invoice);
  assert.ok(text.includes('Subtotal:'));
  assert.ok(text.includes('Discount:'));
  assert.ok(text.includes('VAT:'));
  const lines = text.split('\n');
  const lastLine = lines[lines.length - 1];
  assert.ok(lastLine.startsWith('Total:'));
});

