});

test('renderInvoiceText handles mixed discounted and non-discounted lines', () => {
  const invoice = createInvoice({
    customerId: 'C-003',
    issueDate: '2026-10-07',
    lines: [
      { sku: 'DES-HOUR', qty: 5, discountPercent: 10 },
      { sku: 'DEV-HOUR', qty: 3 },
    ],
  }).value;
  const text = renderInvoiceText(invoice);
  assert.ok(text.includes('Subtotal:'));
  assert.ok(text.includes('Discount:'));
  const lines = text.split('\n');
