  assert.ok(text.includes(issued.dueDate));
});

test('renderInvoiceText does not show due date for draft without issued', () => {
  const invoice = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-07',
    lines: [{ sku: 'WORKSHOP-DAY', qty: 1 }],
  }).value;
  delete invoice.dueDate;
  const text = renderInvoiceText(invoice);
  assert(!text.includes('Due:'));
});

test('renderInvoiceText shows paid amount', () => {
  let invoice = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-07',
    lines: [{ sku: 'WORKSHOP-DAY', qty: 1 }],
