    customerId: 'C-002',
    issueDate: '2026-10-07',
    lines: [{ sku: 'WORKSHOP-DAY', qty: 1 }],
  }).value;
  const text = renderInvoiceText(invoice);
  assert(!text.includes('Paid:'));
});

test('renderInvoiceText shows multiple payments aggregated', () => {
  let invoice = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-07',
    lines: [{ sku: 'WORKSHOP-DAY', qty: 1 }],
  }).value;
  invoice = issueInvoice(invoice, []).value;
  invoice = recordPayment(invoice, { amount: 20000, date: '2026-10-15' }).value;
  invoice = recordPayment(invoice, { amount: 10000, date: '2026-10-20' }).value;
  const text = renderInvoiceText(invoice);
  assert.ok(text.includes('Paid: €300.00'));
});

test('renderInvoiceText line order: total, due, paid', () => {
  let invoice = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-07',
    lines: [{ sku: 'WORKSHOP-DAY', qty: 1 }],
  }).value;
  invoice = issueInvoice(invoice, []).value;
  invoice = recordPayment(invoice, { amount: 20000, date: '2026-10-15' }).value;
  const text = renderInvoiceText(invoice);
  const lines = text.split('\n');
  const totalIndex = lines.findIndex((l) => l.startsWith('Total:'));
  const dueIndex = lines.findIndex((l) => l.startsWith('Due:'));
  const paidIndex = lines.findIndex((l) => l.startsWith('Paid:'));
  assert(totalIndex < dueIndex);
  assert(dueIndex < paidIndex);
});

test('renderInvoiceText with voucher and payments', () => {
